import React from "react";
import MachineCard from "./MachineCard";

const MachineGrid = ({ machines = [] }) => {
  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: "repeat(4, 1fr)",
        gap: "15px"
      }}
    >
      {machines.map((machine) => (
        <MachineCard
          key={machine.machine_id}
          machine={machine}
        />
      ))}
    </div>
  );
};

export default MachineGrid;